namespace Beep.OilandGas.ApiService.Tests;
[Collection("CompanySalesJournalSource")]
public sealed class CompanyForeignSalesJournalTests
{
    internal static async Task<CompanySalesJournalSourceTests.Fixture> PrepareForeign()
    {
        var f=new CompanySalesJournalSourceTests.Fixture();await f.Prepare(taxAndCharges:true);var book=f.Native.Rows.OfType<COMPANY_LEDGER_BOOK>().Single();var creation=CompanyLedgerBookConfigurationProof.Require(book).Command with{FunctionalCurrency="USD",CurrencyDecimals=2};book.FUNCTIONAL_CURRENCY="USD";book.CURRENCY_DECIMALS=2;book.CONFIGURATION_JSON=CompanyLedgerBookConfigurationProof.Create(creation,book);
        foreach(var account in f.Native.Rows.OfType<GL_ACCOUNT>())account.CURRENCY_CODE="USD";foreach(var mapping in f.Native.Rows.OfType<GLAccountMapping>())mapping.CURRENCY_CODE="USD";
        var period=CompanyLedgerPeriodAuthority.Require(f.Period).Command with{CurrencyCode="USD",SourceRevision=CompanyLedgerPeriodReview.Create(f.Current.Company,"administrator","statutory","USD","company-calendar",[]).Revision};f.Period.CURRENCY_CODE="USD";f.Period.AUTHORITY_JSON=CompanyLedgerPeriodAuthority.Create(period,f.Period);
        var books=CompanyLedgerBookReview.Create(f.Current.Company,"administrator",[book]);var empty=CompanyFxRateReview.Create(books,"statutory","KWD",f.Date,[]);var command=CompanyFxRateTests.Command(empty) with{Rate=3.26m,RateDecimals=2,ObservedAtUtc=DateTime.SpecifyKind(f.Date,DateTimeKind.Utc)};var rate=command.CreateRow();rate.ROW_CREATED_BY="administrator";rate.ROW_CREATED_DATE=DateTime.UtcNow;rate.CONFIGURATION_JSON=CompanyFxRateProof.Create(command,rate);f.Native.Rows.Add(rate);
        var types=f.Native.Rows.Select(row=>row.GetType()).Concat([typeof(JOURNAL_ENTRY),typeof(JOURNAL_ENTRY_LINE)]).Distinct().ToDictionary(type=>type==typeof(GLAccountMapping)?"GL_ACCOUNT_MAPPING":type.Name,type=>type);f.Native.Source.Setup(source=>source.GetEntityStructure(It.IsAny<EntityStructure>(),true)).Returns((EntityStructure request,bool refresh)=>new ClassCreator(f.Native.Editor.Object).ConvertToEntityStructure(types[request.EntityName]));return f;
    }
    internal static Task<CompanySalesJournalSourceReview> Read(CompanySalesJournalSourceTests.Fixture f,string? evidenceActor=null,CompanySalesJournalSourceReview? originalSource=null)=>f.Journal.GetCompanySalesJournalSourceAsync(f.Current.Company,f.Receivable.Actor,f.Current.ReceivableId,"statutory","USD","company-calendar",f.Date,f.Selection,f.Receivable.Data.Owner,f.Mappings,f.Periods,f.Receivable.Current,f.Guard,_=>f.Guard(),evidenceActor,originalSource);
    [Fact] public async Task ActualNativeForeignSourcePreservesOriginalMoneyAndIndependentReaderView()
    {
        using var validation=CompanySalesInvoiceValidation.Enter();var f=await PrepareForeign();var source=await Read(f);Assert.Equal("KWD",source.SourceCurrencyCode);Assert.Equal("USD",source.CurrencyCode);Assert.NotNull(source.Conversion);Assert.Equal(source.Receivable.Receivables.Single().ProposedTotal,source.Conversion!.SourceTotal);Assert.Equal(source.FunctionalTotal,source.Lines.Sum(line=>line.Debit));Assert.Equal(source.FunctionalTotal,source.Lines.Sum(line=>line.Credit));Assert.All(source.Lines,line=>Assert.Equal(decimal.Round(line.Debit,2),line.Debit));
        await using var host=await CompanySalesJournalSourceHttpTests.Start(f);using var company=CompanyGLAccountHttpTests.Selected(actor:f.Current.ActorUserId,grants:CompanySalesJournalSourceHttpTests.Grants);var client=CompanyGLAccountHttpTests.Client(host.Client,company);var actual=await client.GetCompanySalesJournalSourceAsync(source.ReceivableId,"statutory","USD","company-calendar",f.Date,f.Selection);Assert.Equal(JsonSerializer.Serialize(source),JsonSerializer.Serialize(actual));
        var legacyRates=await f.Accounts.GetOriginalCompanyFxReviewAsync(source.Company,source.ActorUserId,source.BookId,source.SourceCurrencyCode,f.Date,null,f.Guard);var legacy=CompanySalesJournalSourceReview.Create(f.Current,source.Mappings,CompanyLedgerPeriodReview.Create(source.Company,source.ActorUserId,source.BookId,source.CurrencyCode,source.CalendarId,[f.Period]),f.Date,f.Selection,source.Books,legacyRates);var legacyJson=JsonSerializer.Serialize(legacy);Assert.DoesNotContain("Window",legacyJson);var old=JsonSerializer.Deserialize<CompanySalesJournalSourceReview>(legacyJson)!;Assert.Equal(legacyJson,JsonSerializer.Serialize(await Read(f,originalSource:old)));Assert.Throws<InvalidOperationException>(()=>new CompanySalesJournalPreparation(Guid.NewGuid().ToString("N"),Guid.NewGuid().ToString("N"),old,"old-scope-draft","Original source",old.Lines.Select(_=>Guid.NewGuid().ToString("N")).ToArray()).RequireCurrent(source));
        var actor=f.Receivable.Actor;f.Receivable.Actor="independent-reviewer";var reviewed=await Read(f,actor);Assert.Equal(JsonSerializer.Serialize(source),JsonSerializer.Serialize(reviewed));f.NoWrites();
        var rate=f.Native.Rows.OfType<FX_RATE>().Single();f.Native.Rows.Remove(rate);await Assert.ThrowsAsync<InvalidOperationException>(()=>Read(f,actor));f.Native.Rows.Add(rate);rate.RATE=3.27m;await Assert.ThrowsAnyAsync<Exception>(()=>Read(f,actor));f.NoWrites();
    }
    [Fact] public async Task ForeignNativePreparationReviewAtomicPostingAndRecoveryPreserveSourceARAndFunctionalLedger()
    {
        using var validation=CompanySalesInvoiceValidation.Enter();var f=await PrepareForeign();var source=await Read(f);var baseline=new CompanySalesJournalPreparationTests.ApprovedSourceFixture{Source=source,Receivable=CompanyInventorySourceReview.Copy(f.Current.Original.Receivable),NativeFixture=f};var posting=new CompanySalesJournalPostingTests.Fixture(source);await posting.Prepare(baseline);var original=JsonSerializer.Serialize(baseline.Receivable);var outcome=await posting.Post();outcome.Require(posting.Command);Assert.Equal("USD",outcome.Journal.Header.CURRENCY_CODE);Assert.Equal(source.FunctionalTotal,outcome.Journal.Header.TOTAL_DEBIT);Assert.All(outcome.Entries,entry=>Assert.Equal("USD",entry.CURRENCY_CODE));Assert.Equal(original,JsonSerializer.Serialize(outcome.Receivable));Assert.Equal("KWD",outcome.Receivable.CURRENCY_CODE);Assert.Equal(source.FunctionalTotal,outcome.Entries.Sum(entry=>entry.DEBIT_AMOUNT));Assert.Equal(source.FunctionalTotal,outcome.Entries.Sum(entry=>entry.CREDIT_AMOUNT));var writes=posting.Reviewed.Draft.Native.Writes;var recovery=await posting.Recover();Assert.Equal(JsonSerializer.Serialize(outcome),JsonSerializer.Serialize(recovery.Outcome));Assert.Equal(JsonSerializer.Serialize(outcome),JsonSerializer.Serialize(await posting.Post()));Assert.Equal(writes,posting.Reviewed.Draft.Native.Writes);
        var ledger=await posting.Reviewed.Draft.Service.GetCompanySalesPostedLedgerAsync(source.Company,"readonly-accountant",source.BindingRevision,"statutory","USD",source.ReceivableId,posting.AR,posting.Guard,posting.Field);ledger.Require(source.Company,"readonly-accountant","statutory","USD",source.ReceivableId);Assert.Equal(JsonSerializer.Serialize(source.Conversion),JsonSerializer.Serialize(Assert.Single(ledger.Journals).Conversion));var json=JsonSerializer.Serialize(ledger);Assert.DoesNotContain("CONFIGURATION_JSON",json);Assert.DoesNotContain("WORKFLOW_JSON",json);Assert.DoesNotContain("BindingRevision",JsonSerializer.Serialize(ledger.Journals));Assert.Equal(writes,posting.Reviewed.Draft.Native.Writes);
    }
}
#endif
